import{_ as o,a0 as s,w as p,s as i,ao as d,I as l,x as e,a1 as n,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"给开源项目贡献代码时：先讨论，再编码 | LCTT x X-CMD","titleTemplate":false,"description":"给开源项目贡献代码时：先讨论，再编码 | LCTT (202006) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"给开源项目贡献代码时：先讨论，再编码 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"给开源项目贡献代码时：先讨论，再编码 | LCTT (202006) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202006/20190218 Talk, then code","title":"给开源项目贡献代码时：先讨论，再编码","tag":"202006","desc":""},"relativePath":"202006/20190218 Talk, then code.md","filePath":"[post].md"}'),u={name:"202006/20190218 Talk, then code.md"};function f(h,t,T,m,b,x){const a=s("Link");return p(),i("div",null,[t[15]||(t[15]=d('<h1 id="给开源项目贡献代码时-先讨论-再编码" tabindex="-1">给开源项目贡献代码时：先讨论，再编码 <a class="header-anchor" href="#给开源项目贡献代码时-先讨论-再编码" aria-label="Permalink to “给开源项目贡献代码时：先讨论，再编码”">​</a></h1><p>我所参与的开源项目遵循的是一种这样的理念，我把它描述为 “先讨论，再编码”。我认为一般来说这是开发软件的好方法，我想花一点时间来谈谈这种方法的好处。</p><h3 id="避免伤害感情" tabindex="-1">避免伤害感情 <a class="header-anchor" href="#避免伤害感情" aria-label="Permalink to “避免伤害感情”">​</a></h3><p>先讨论你想做的改变最重要的原因是避免伤害感情。我经常看到一个贡献者闭门造车地提交了一个 PR，却发现他的努力工作被拒绝了。这可能有一堆原因：PR 太大了，PR 没有遵循本地风格，PR 修复了一个对项目不重要的问题或者最近间接修复了的问题，等等。</p><p>这些问题的根本原因都是缺乏沟通。“先讨论，再编码” 理念的目标不是阻碍你或给你带来挫折，而是确保一个功能第一次就能正确落地，而不至于产生大量的维护债务。无论是改动的作者，还是审查者，当一个改动突然出现时，并暗示说 “好吧，我已经做完了，你要做的就是合并它，对吧？”，先讨论可以让他们不必背负伤害感情的情绪负担。</p><h3 id="讨论应该如何进行" tabindex="-1">讨论应该如何进行？ <a class="header-anchor" href="#讨论应该如何进行" aria-label="Permalink to “讨论应该如何进行？”">​</a></h3><p>每一个新功能或错误修复都应该在工作开始前与项目的维护者讨论。私下试验是可以的，但不要在没有讨论之前就发送修改。</p><p>对于简单的改动，“讨论” 的定义可以只是 GitHub 议题中的一个设计草图。如果你的 PR 修复了一个 bug，你应该链接到它修复的 bug。如果没有，你应该先提出一个 bug，等待维护者确认后再发送 PR。这可能看起来有点落后 —— 谁不希望一个 bug 被修复呢 —— 但考虑到这个 bug 可能是对软件工作方式的误解，也可能是一个更大问题的症状，这需要进一步调查。</p><p>对于比较复杂的改动，尤其是功能请求，我建议在发送代码之前，先分发一份设计文档并达成一致。这不一定是一个完整的文档，发一个议题，带个草图可能就足够了，但关键是在用代码搞定之前，先用文字达成一致。</p><p>在任何情况下，你都不应该继续发送你的代码，直到维护者同意你的方法是他们所满意的。拉取请求是日常生活，而不仅仅是为了赶着过节。</p><h3 id="代码审查-而不是由委员会设计" tabindex="-1">代码审查，而不是由委员会设计 <a class="header-anchor" href="#代码审查-而不是由委员会设计" aria-label="Permalink to “代码审查，而不是由委员会设计”">​</a></h3><p>代码审查不是争论设计的地方。这有两个原因。首先，大多数代码审查工具都不适合长长的评论会话，GitHub 的 PR 界面在这方面非常糟糕，Gerrit 比较好，但很少有管理员团队会维护 Gerrit 实例。更重要的是，在代码审查阶段就出现了分歧，说明大家对如何实现这个变化并没有达成一致。</p><hr><p>讨论你想写的代码，然后再写你所讨论的代码。请不要反其道而行之。</p><hr>',15)),l("p",null,[t[1]||(t[1]=e("via: ",-1)),n(a,{href:"https://dave.cheney.net/2019/02/18/talk-then-code"},{default:r(()=>[...t[0]||(t[0]=[e("https://dave.cheney.net/2019/02/18/talk-then-code",-1)])]),_:1})]),l("p",null,[t[6]||(t[6]=e("作者：",-1)),n(a,{href:"https://dave.cheney.net/author/davecheney"},{default:r(()=>[...t[2]||(t[2]=[e("Dave Cheney",-1)])]),_:1}),t[7]||(t[7]=e(" 选题：",-1)),n(a,{href:"https://github.com/lujun9972"},{default:r(()=>[...t[3]||(t[3]=[e("lujun9972",-1)])]),_:1}),t[8]||(t[8]=e(" 译者：",-1)),n(a,{href:"https://github.com/wxy"},{default:r(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1}),t[9]||(t[9]=e(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:r(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[12]||(t[12]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原创编译，",-1)),n(a,{href:"https://linux.cn/"},{default:r(()=>[...t[11]||(t[11]=[e("Linux中国",-1)])]),_:1}),t[14]||(t[14]=e(" 荣誉推出",-1))])])}const k=o(u,[["render",f]]);export{g as __pageData,k as default};
